/**
 * Types for `recommendation_data.json` — the offline artifact generated by
 * `data/build_recommendation_data.py`.
 *
 * The web app imports this artifact once and performs all
 * scoring/optimization locally against the learned paired model. See
 * `web/src/services/recommendationEngine.ts` for the scoring logic and
 * README.md "Recommendation pipeline" for the end-to-end design.
 */

/** Feature-family prefixes used in the flat weight/support maps. */
export type FeatureFamily =
  | 'H'
  | 'S'
  | 'HP'
  | 'HS'
  | 'SP'
  | 'M'
  | 'MP'
  | 'MC'
  | 'MX'
  | 'HMX'
  | 'HM'
  | 'HC'
  | 'HSM'
  | 'HTM'
  | 'B'
  | 'BM';

export interface RecommendationSchema {
  version: number;
  model_type: string;
  feature_families: Record<string, string>;
  default_skill_index: number;
}

export interface RecommendationCatalog {
  catalog_version: string;
  mechanics_version?: string;
  hero_count: number;
  skill_count: number;
  /** hero name → its default (signature) skill; that skill is not a draftable feature. */
  default_skill: Record<string, string>;
}

export interface BattleCounts {
  total_battles: number;
  team1_wins: number;
  team2_wins: number;
  invalid_battles: number;
  /**
   * Deterministic content hash of the validated training corpus. Identifies the
   * battles the artifact was built from without any wall-clock timestamp — the
   * artifact is byte-reproducible, so there is no `generated_at`/`added_battles`.
   */
  corpus_version: string;
}

export type StatusRecipientScope = 'self' | 'ally' | 'team' | 'enemy' | 'unknown';

export interface StatusMechanicEvent {
  status: string;
  recipient_scope: StatusRecipientScope;
  probability: number;
}

export interface SkillMechanics {
  probability: number;
  features: Record<string, number>;
  provides: string[];
  consumes: string[];
  provides_events?: StatusMechanicEvent[];
  consumes_events?: StatusMechanicEvent[];
  provides_scopes?: Record<string, StatusRecipientScope[]>;
  consumes_scopes?: Record<string, StatusRecipientScope[]>;
  removes: string[];
  immunities: string[];
  counters: string[];
  references: string[];
}

export interface HeroMechanics {
  signature: string;
  camp: string;
  troop: string;
  stats: Record<string, number>;
  normalized_stats: Record<string, number>;
}

export interface BondMechanics extends SkillMechanics {
  required_members: number;
  members: string[];
  recipient_scope: 'active_members';
}

export interface RecommendationMechanics {
  schema_version: number;
  mechanics_version: string;
  default_skill: Record<string, string>;
  statuses: Record<
    string,
    { family: string; negative: boolean; controlling: boolean }
  >;
  heroes: Record<string, HeroMechanics>;
  skills: Record<string, SkillMechanics>;
  bonds: Record<string, BondMechanics>;
  audit: {
    skill_count: number;
    token_count: number;
    reference_only_status_mentions: Record<string, string[]>;
    unknown_status_terms: Record<string, string[]>;
    unknown_bond_status_terms: Record<string, string[]>;
    hero_count: number;
    bond_count: number;
  };
}

export interface PairedModel {
  intercept: number;
  l2_C: number;
  min_support_single: number;
  min_support_pair: number;
  popularity_penalty_gamma?: number;
  popularity_exposure_tau?: number;
  n_features: number;
  /** feature id → fitted logistic weight (relative roster-strength contribution). */
  weights: Record<string, number>;
  /** feature id → number of battles it appeared in (evidence/support). */
  support: Record<string, number>;
  /** Offline-parsed current game mechanics; absent on legacy/test artifacts. */
  mechanics?: RecommendationMechanics | null;
}

export interface AnalyticsRow {
  name: string;
  wins: number;
  losses: number;
  total: number;
  win_rate: number;
  smoothed_win_rate: number;
  /** Number of observations explicitly carrying upstream 影 provenance. */
  shadow_total?: number;
}

export interface RecommendationAnalytics {
  prior_win_rate: number;
  heroes: AnalyticsRow[];
  skills: AnalyticsRow[];
}

export interface BacktestMetrics {
  n_train?: number;
  n_test: number;
  accuracy: number | null;
  log_loss: number | null;
  brier: number | null;
  holdout_frac: number;
  baseline_accuracy?: number;
  note?: string;
}

export interface RecommendationData {
  schema: RecommendationSchema;
  catalog: RecommendationCatalog;
  battle_counts: BattleCounts;
  model: PairedModel;
  analytics: RecommendationAnalytics;
  backtest: BacktestMetrics;
}
